-- Fixed read-only CURRENT COMPANY catalogue and guard observation.
-- No business rows, identifiers, account policies or runtime MACs are selected.
SELECT jsonb_build_object(
'schema',current_schema(),
'readOnly',current_setting('transaction_read_only'),
'relations',(SELECT COALESCE(jsonb_agg(to_jsonb(x)),'[]'::jsonb) FROM (SELECT c.relname AS name,c.relkind::text AS kind,c.relpersistence::text AS persistence,c.relispartition AS partition,c.relrowsecurity AS rls,c.relforcerowsecurity AS forced,c.relowner=(SELECT oid FROM pg_roles WHERE rolname=current_user) AS "ownedByCurrentUser",c.relacl::text AS acl,c.reloptions AS options,c.relreplident::text AS "replicaIdentity",c.reltablespace=0 AS "defaultTablespace",EXISTS(SELECT 1 FROM pg_inherits i WHERE i.inhparent=c.oid OR i.inhrelid=c.oid) AS inherited,EXISTS(SELECT 1 FROM pg_rewrite w WHERE w.ev_class=c.oid AND w.rulename<>'_RETURN') AS rewritten FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND c.relkind IN ('r','p','v','m','f') ORDER BY c.relname) x),
'columns',(SELECT COALESCE(jsonb_agg(to_jsonb(x)),'[]'::jsonb) FROM (SELECT c.relname AS "table",a.attname AS name,a.attnum::int AS position,format_type(a.atttypid,a.atttypmod) AS type,a.attnotnull AS "notNull",a.attidentity::text AS identity,a.attgenerated::text AS generated,pg_get_expr(d.adbin,d.adrelid) AS "defaultExpression",a.attacl::text AS acl,CASE WHEN a.attcollation=0 THEN NULL ELSE co.collname END AS collation,CASE WHEN a.attcollation=0 THEN NULL ELSE (SELECT nspname FROM pg_namespace WHERE oid=co.collnamespace) END AS "collationSchema" FROM pg_attribute a JOIN pg_class c ON c.oid=a.attrelid JOIN pg_namespace n ON n.oid=c.relnamespace LEFT JOIN pg_attrdef d ON d.adrelid=a.attrelid AND d.adnum=a.attnum LEFT JOIN pg_collation co ON co.oid=a.attcollation WHERE n.nspname='public' AND c.relkind IN ('r','p','v','m','f') AND a.attnum>0 AND NOT a.attisdropped ORDER BY c.relname,a.attnum) x),
'foreignKeys',(SELECT COALESCE(jsonb_agg(to_jsonb(x)),'[]'::jsonb) FROM (SELECT child.relname AS child,parent.relname AS parent,childns.nspname AS "childSchema",parentns.nspname AS "parentSchema",ARRAY(SELECT a.attname::text FROM unnest(c.conkey) WITH ORDINALITY k(n,p) JOIN pg_attribute a ON a.attrelid=c.conrelid AND a.attnum=k.n ORDER BY k.p) AS local,ARRAY(SELECT a.attname::text FROM unnest(c.confkey) WITH ORDINALITY k(n,p) JOIN pg_attribute a ON a.attrelid=c.confrelid AND a.attnum=k.n ORDER BY k.p) AS remote FROM pg_constraint c JOIN pg_class child ON child.oid=c.conrelid JOIN pg_namespace childns ON childns.oid=child.relnamespace JOIN pg_class parent ON parent.oid=c.confrelid JOIN pg_namespace parentns ON parentns.oid=parent.relnamespace WHERE c.contype='f' AND (childns.nspname='public' OR parentns.nspname='public') ORDER BY child.relname,c.conname) x),
'guards',(SELECT COALESCE(jsonb_agg(to_jsonb(x)),'[]'::jsonb) FROM (SELECT c.relname AS "table",t.tgname AS name,t.tgenabled::text AS enabled,t.tgtype::int AS mask,t.tgqual::text AS condition,t.tgattr::text AS attributes,ARRAY(SELECT a.attname::text FROM unnest(t.tgattr::smallint[]) WITH ORDINALITY k(n,p) JOIN pg_attribute a ON a.attrelid=t.tgrelid AND a.attnum=k.n ORDER BY k.p) AS "attributeNames",encode(t.tgargs,'hex') AS args,t.tgnargs::int AS "argumentCount",t.tgconstraint<>0 AS "constraintTrigger",t.tgdeferrable AS deferrable,t.tginitdeferred AS deferred,t.tgoldtable AS "oldTransitionTable",t.tgnewtable AS "newTransitionTable",pn.nspname AS "functionSchema",p.proname AS "functionName",encode(sha256(convert_to(p.prosrc,'UTF8')),'hex') AS "bodySha256",p.prosecdef AS definer,l.lanname AS language,p.proowner=(SELECT oid FROM pg_roles WHERE rolname=current_user) AS "ownedByCurrentUser",p.prokind::text AS "functionKind",p.proretset AS "returnsSet",format_type(p.prorettype,NULL) AS "returnType",p.pronargs::int AS "functionArgumentCount",p.proargtypes::text AS "functionArgumentTypes",p.proconfig AS settings,p.proacl::text AS acl,p.probin AS binary,p.proisstrict AS strict,p.proleakproof AS leakproof,p.provolatile::text AS volatility,p.proparallel::text AS parallel,p.procost::text AS cost,p.prorows::text AS rows,p.prosupport::regproc::text AS support FROM pg_trigger t JOIN pg_class c ON c.oid=t.tgrelid JOIN pg_namespace n ON n.oid=c.relnamespace JOIN pg_proc p ON p.oid=t.tgfoid JOIN pg_namespace pn ON pn.oid=p.pronamespace JOIN pg_language l ON l.oid=p.prolang WHERE n.nspname='public' AND NOT t.tgisinternal ORDER BY c.relname,t.tgname) x),
'operational',jsonb_build_object('relations',(SELECT COALESCE(jsonb_agg(to_jsonb(x)),'[]'::jsonb) FROM (SELECT c.relname AS name,c.relkind::text AS kind,c.relpersistence::text AS persistence,c.relispartition AS partition,c.relrowsecurity AS rls,c.relforcerowsecurity AS forced,c.relowner=(SELECT oid FROM pg_roles WHERE rolname=current_user) AS "ownedByCurrentUser",c.relacl::text AS acl,c.reloptions AS options,c.relreplident::text AS "replicaIdentity",c.reltablespace=0 AS "defaultTablespace",EXISTS(SELECT 1 FROM pg_inherits i WHERE i.inhparent=c.oid OR i.inhrelid=c.oid) AS inherited,EXISTS(SELECT 1 FROM pg_rewrite w WHERE w.ev_class=c.oid AND w.rulename<>'_RETURN') AS rewritten FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND c.relname=ANY(ARRAY['InventoryWarehouseEditAudit','InvoiceQrSupplierLearning','InvoiceStockExclusionEmail','PosInternalTransfer','PosInternalTransferLine','PosInternalTransferSettlement','PosPackageStockPosting','PosScannedCashReturn','StoreStockPackage']::text[]) ORDER BY c.relname) x),'columns',(SELECT COALESCE(jsonb_agg(to_jsonb(x)),'[]'::jsonb) FROM (SELECT c.relname AS "table",a.attname AS name,a.attnum::int AS position,format_type(a.atttypid,a.atttypmod) AS type,a.attnotnull AS "notNull",a.attidentity::text AS identity,a.attgenerated::text AS generated,pg_get_expr(d.adbin,d.adrelid) AS "defaultExpression",a.attacl::text AS acl,CASE WHEN a.attcollation=0 THEN NULL ELSE co.collname END AS collation,CASE WHEN a.attcollation=0 THEN NULL ELSE (SELECT nspname FROM pg_namespace WHERE oid=co.collnamespace) END AS "collationSchema" FROM pg_attribute a JOIN pg_class c ON c.oid=a.attrelid JOIN pg_namespace n ON n.oid=c.relnamespace LEFT JOIN pg_attrdef d ON d.adrelid=a.attrelid AND d.adnum=a.attnum LEFT JOIN pg_collation co ON co.oid=a.attcollation WHERE n.nspname='public' AND c.relname=ANY(ARRAY['InventoryWarehouseEditAudit','InvoiceQrSupplierLearning','InvoiceStockExclusionEmail','PosInternalTransfer','PosInternalTransferLine','PosInternalTransferSettlement','PosPackageStockPosting','PosScannedCashReturn','StoreStockPackage']::text[]) AND a.attnum>0 AND NOT a.attisdropped ORDER BY c.relname,a.attnum) x),'constraints',(SELECT COALESCE(jsonb_agg(to_jsonb(x)),'[]'::jsonb) FROM (SELECT ns.nspname AS schema,t.relname AS "table",c.conname AS name,c.contype::text AS kind,c.condeferrable AS "deferrable",c.condeferred AS deferred,c.convalidated AS validated,pns.nspname AS "parentSchema",p.relname AS "parentTable",c.confdeltype::text AS "onDelete",c.confupdtype::text AS "onUpdate",pg_get_constraintdef(c.oid,true) AS definition FROM pg_constraint c JOIN pg_class t ON t.oid=c.conrelid JOIN pg_namespace ns ON ns.oid=t.relnamespace LEFT JOIN pg_class p ON p.oid=c.confrelid LEFT JOIN pg_namespace pns ON pns.oid=p.relnamespace WHERE c.contype<>'n' AND ((ns.nspname='public' AND t.relname=ANY(ARRAY['InventoryWarehouseEditAudit','InvoiceQrSupplierLearning','InvoiceStockExclusionEmail','PosInternalTransfer','PosInternalTransferLine','PosInternalTransferSettlement','PosPackageStockPosting','PosScannedCashReturn','StoreStockPackage']::text[])) OR (pns.nspname='public' AND p.relname=ANY(ARRAY['InventoryWarehouseEditAudit','InvoiceQrSupplierLearning','InvoiceStockExclusionEmail','PosInternalTransfer','PosInternalTransferLine','PosInternalTransferSettlement','PosPackageStockPosting','PosScannedCashReturn','StoreStockPackage']::text[]))) ORDER BY ns.nspname,t.relname,c.conname) x),'indexes',(SELECT COALESCE(jsonb_agg(to_jsonb(x)),'[]'::jsonb) FROM (SELECT c.relname AS "table",ic.relname AS name,pg_get_indexdef(i.indexrelid) AS definition,i.indisprimary AS "primary",i.indisunique AS "unique",i.indisvalid AS valid,i.indisready AS ready,i.indimmediate AS immediate,i.indisreplident AS "replicaIdentity",ic.relowner=(SELECT oid FROM pg_roles WHERE rolname=current_user) AS "ownedByCurrentUser",ic.reloptions AS options FROM pg_index i JOIN pg_class c ON c.oid=i.indrelid JOIN pg_class ic ON ic.oid=i.indexrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND c.relname=ANY(ARRAY['InventoryWarehouseEditAudit','InvoiceQrSupplierLearning','InvoiceStockExclusionEmail','PosInternalTransfer','PosInternalTransferLine','PosInternalTransferSettlement','PosPackageStockPosting','PosScannedCashReturn','StoreStockPackage']::text[]) ORDER BY c.relname,ic.relname) x),'triggers',(SELECT COALESCE(jsonb_agg(to_jsonb(x)),'[]'::jsonb) FROM (SELECT c.relname AS "table",t.tgname AS name,t.tgenabled::text AS enabled,t.tgtype::int AS mask,t.tgqual::text AS condition,ARRAY(SELECT a.attname::text FROM unnest(t.tgattr::smallint[]) WITH ORDINALITY k(n,p) JOIN pg_attribute a ON a.attrelid=t.tgrelid AND a.attnum=k.n ORDER BY k.p) AS "attributeNames",encode(t.tgargs,'hex') AS args,t.tgnargs::int AS "argumentCount",t.tgconstraint<>0 AS "constraintTrigger",t.tgdeferrable AS deferrable,t.tginitdeferred AS deferred,t.tgoldtable AS "oldTransitionTable",t.tgnewtable AS "newTransitionTable",pn.nspname AS "functionSchema",p.proname AS "functionName",p.prosrc AS body,p.prosecdef AS definer,l.lanname AS language,p.proowner=(SELECT oid FROM pg_roles WHERE rolname=current_user) AS "ownedByCurrentUser",p.prokind::text AS "functionKind",p.proretset AS "returnsSet",format_type(p.prorettype,NULL) AS "returnType",p.pronargs::int AS "functionArgumentCount",p.proargtypes::text AS "functionArgumentTypes",p.proconfig AS settings,p.proacl::text AS acl,p.probin AS binary,p.proisstrict AS strict,p.proleakproof AS leakproof,p.provolatile::text AS volatility,p.proparallel::text AS parallel,p.procost::text AS cost,p.prorows::text AS rows,p.prosupport::regproc::text AS support FROM pg_trigger t JOIN pg_class c ON c.oid=t.tgrelid JOIN pg_namespace n ON n.oid=c.relnamespace JOIN pg_proc p ON p.oid=t.tgfoid JOIN pg_namespace pn ON pn.oid=p.pronamespace JOIN pg_language l ON l.oid=p.prolang WHERE n.nspname='public' AND NOT t.tgisinternal AND (c.relname=ANY(ARRAY['InventoryWarehouseEditAudit','InvoiceQrSupplierLearning','InvoiceStockExclusionEmail','PosInternalTransfer','PosInternalTransferLine','PosInternalTransferSettlement','PosPackageStockPosting','PosScannedCashReturn','StoreStockPackage']::text[]) OR (c.relname='StoreProduct' AND t.tgname='mws_guard_package_stock_change')) ORDER BY c.relname,t.tgname) x)),
'supplier',jsonb_build_object('relations',(SELECT COALESCE(jsonb_agg(to_jsonb(x)),'[]'::jsonb) FROM (SELECT c.relname AS name,c.relkind::text AS kind,c.relpersistence::text AS persistence,c.relispartition AS partition,c.relrowsecurity AS rls,c.relforcerowsecurity AS forced,c.relowner=(SELECT oid FROM pg_roles WHERE rolname=current_user) AS "ownedByCurrentUser",c.relacl::text AS acl,c.reloptions AS options,c.relreplident::text AS "replicaIdentity",c.reltablespace=0 AS "defaultTablespace",EXISTS(SELECT 1 FROM pg_inherits i WHERE i.inhparent=c.oid OR i.inhrelid=c.oid) AS inherited,EXISTS(SELECT 1 FROM pg_rewrite w WHERE w.ev_class=c.oid AND w.rulename<>'_RETURN') AS rewritten FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND c.relname=ANY(ARRAY['AutomaticReportSupplierComparisonConsent']::text[]) ORDER BY c.relname) x),'columns',(SELECT COALESCE(jsonb_agg(to_jsonb(x)),'[]'::jsonb) FROM (SELECT c.relname AS "table",a.attname AS name,a.attnum::int AS position,format_type(a.atttypid,a.atttypmod) AS type,a.attnotnull AS "notNull",a.attidentity::text AS identity,a.attgenerated::text AS generated,pg_get_expr(d.adbin,d.adrelid) AS "defaultExpression",a.attacl::text AS acl,CASE WHEN a.attcollation=0 THEN NULL ELSE co.collname END AS collation,CASE WHEN a.attcollation=0 THEN NULL ELSE (SELECT nspname FROM pg_namespace WHERE oid=co.collnamespace) END AS "collationSchema" FROM pg_attribute a JOIN pg_class c ON c.oid=a.attrelid JOIN pg_namespace n ON n.oid=c.relnamespace LEFT JOIN pg_attrdef d ON d.adrelid=a.attrelid AND d.adnum=a.attnum LEFT JOIN pg_collation co ON co.oid=a.attcollation WHERE n.nspname='public' AND c.relname=ANY(ARRAY['AutomaticReportSupplierComparisonConsent']::text[]) AND a.attnum>0 AND NOT a.attisdropped ORDER BY c.relname,a.attnum) x),'constraints',(SELECT COALESCE(jsonb_agg(to_jsonb(x)),'[]'::jsonb) FROM (SELECT ns.nspname AS schema,t.relname AS "table",c.conname AS name,c.contype::text AS kind,c.condeferrable AS "deferrable",c.condeferred AS deferred,c.convalidated AS validated,pns.nspname AS "parentSchema",p.relname AS "parentTable",c.confdeltype::text AS "onDelete",c.confupdtype::text AS "onUpdate",pg_get_constraintdef(c.oid,true) AS definition FROM pg_constraint c JOIN pg_class t ON t.oid=c.conrelid JOIN pg_namespace ns ON ns.oid=t.relnamespace LEFT JOIN pg_class p ON p.oid=c.confrelid LEFT JOIN pg_namespace pns ON pns.oid=p.relnamespace WHERE c.contype<>'n' AND ((ns.nspname='public' AND t.relname=ANY(ARRAY['AutomaticReportSupplierComparisonConsent']::text[])) OR (pns.nspname='public' AND p.relname=ANY(ARRAY['AutomaticReportSupplierComparisonConsent']::text[]))) ORDER BY ns.nspname,t.relname,c.conname) x),'indexes',(SELECT COALESCE(jsonb_agg(to_jsonb(x)),'[]'::jsonb) FROM (SELECT c.relname AS "table",ic.relname AS name,pg_get_indexdef(i.indexrelid) AS definition,i.indisprimary AS "primary",i.indisunique AS "unique",i.indisvalid AS valid,i.indisready AS ready,i.indimmediate AS immediate,i.indisreplident AS "replicaIdentity",ic.relowner=(SELECT oid FROM pg_roles WHERE rolname=current_user) AS "ownedByCurrentUser",ic.reloptions AS options FROM pg_index i JOIN pg_class c ON c.oid=i.indrelid JOIN pg_class ic ON ic.oid=i.indexrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND c.relname=ANY(ARRAY['AutomaticReportSupplierComparisonConsent']::text[]) ORDER BY c.relname,ic.relname) x),'triggers',(SELECT COALESCE(jsonb_agg(to_jsonb(x)),'[]'::jsonb) FROM (SELECT c.relname AS "table",t.tgname AS name,t.tgenabled::text AS enabled,t.tgtype::int AS mask,t.tgqual::text AS condition,ARRAY(SELECT a.attname::text FROM unnest(t.tgattr::smallint[]) WITH ORDINALITY k(n,p) JOIN pg_attribute a ON a.attrelid=t.tgrelid AND a.attnum=k.n ORDER BY k.p) AS "attributeNames",encode(t.tgargs,'hex') AS args,t.tgnargs::int AS "argumentCount",t.tgconstraint<>0 AS "constraintTrigger",t.tgdeferrable AS deferrable,t.tginitdeferred AS deferred,t.tgoldtable AS "oldTransitionTable",t.tgnewtable AS "newTransitionTable",pn.nspname AS "functionSchema",p.proname AS "functionName",p.prosrc AS body,p.prosecdef AS definer,l.lanname AS language,p.proowner=(SELECT oid FROM pg_roles WHERE rolname=current_user) AS "ownedByCurrentUser",p.prokind::text AS "functionKind",p.proretset AS "returnsSet",format_type(p.prorettype,NULL) AS "returnType",p.pronargs::int AS "functionArgumentCount",p.proargtypes::text AS "functionArgumentTypes",p.proconfig AS settings,p.proacl::text AS acl,p.probin AS binary,p.proisstrict AS strict,p.proleakproof AS leakproof,p.provolatile::text AS volatility,p.proparallel::text AS parallel,p.procost::text AS cost,p.prorows::text AS rows,p.prosupport::regproc::text AS support FROM pg_trigger t JOIN pg_class c ON c.oid=t.tgrelid JOIN pg_namespace n ON n.oid=c.relnamespace JOIN pg_proc p ON p.oid=t.tgfoid JOIN pg_namespace pn ON pn.oid=p.pronamespace JOIN pg_language l ON l.oid=p.prolang WHERE n.nspname='public' AND NOT t.tgisinternal AND (c.relname=ANY(ARRAY['AutomaticReportSupplierComparisonConsent']::text[])) ORDER BY c.relname,t.tgname) x)),
 'fences',(SELECT COALESCE(jsonb_agg(to_jsonb(f)),'[]'::jsonb) FROM (SELECT "planHash",count(*)::integer AS count,count(*) FILTER(WHERE "maintenance")::integer AS "maintenanceCount",count(*) FILTER(WHERE "retired")::integer AS "retiredCount",count(*) FILTER(WHERE "operationId" IS NOT NULL)::integer AS "operationNotNullCount",min("generation")::text AS "minGeneration",max("generation")::text AS "maxGeneration" FROM "StoreLifecycleFence" GROUP BY "planHash" ORDER BY "planHash") f),
 'currentChecks',(SELECT COALESCE(jsonb_agg(to_jsonb(x)),'[]'::jsonb) FROM (SELECT t.relname AS "table",c.conname AS name,c.contype::text AS kind,c.convalidated AS validated,c.condeferrable AS deferrable,c.condeferred AS deferred,pg_get_constraintdef(c.oid,true) AS definition FROM pg_constraint c JOIN pg_class t ON t.oid=c.conrelid JOIN pg_namespace n ON n.oid=t.relnamespace WHERE n.nspname='public' AND t.relname IN ('PurchaseOrder','StoreProduct','TableOrder') AND c.contype='c' ORDER BY t.relname,c.conname) x),
'nonFinalOperations',(SELECT count(*)::integer FROM "StoreLifecycleExecution" WHERE "state" NOT IN ('COMPLETED','REOPENED','ABORTED'))
);
